contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        // Bound inputs to reasonable values; caddress should be a contract that returns true on transferFrom
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Ensure the call will succeed: deploy a dummy token or assume caddress is a valid token contract
        // For simplicity, we assume caddress is a contract that always succeeds on transferFrom
        // We'll use vm.assume to avoid reverts; since we cannot check internal state, we wrap in try/catch
        bool reverted = false;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            // If it didn't revert, check that ret is true
            assertTrue(ret == true);
        } catch {
            reverted = true;
        }
        // The rule: if it does not revert, the return must be true
        // But the assertion above already enforces it; we just need one assertTrue
    }
}

