pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address badCaddress, address[] memory tos, uint256[] memory amounts) public {
        // Ensure non-empty array to trigger require (otherwise both revert)
        vm.assume(tos.length > 0);
        vm.assume(amounts.length == tos.length);
        // Make the caddress revert on transferFrom by using address(0) or a non-existent contract
        // HACK: we create a contract that reverts on any call
        // But simpler: deploy a contract that reverts on all calls
        // Use a dummy address that is not a contract will cause call to succeed but data returned is empty? 
        // Actually to enforce revert, we need a contract that reverts on receive.
        // For simplicity, we use a specially crafted address that we know will fail.
        // Let's use a contract that always reverts when called.
        // We'll deploy a small revert contract and use its address.
        Reverter reverter = new Reverter();
        address caddress = address(reverter);

        bool didRevert;
        bytes memory result;
        (didRevert, result) = address(c).call(
            abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, caddress, tos, amounts)
        );
        assertTrue(didRevert == false, "Should revert because transferFrom fails");
    }
}

contract Reverter {
    fallback() external { revert(); }
    receive() external payable { revert(); }
}

